#include <stdio.h>
#include <string.h>
#include "block.h"
static int label_index(const Quad*q,int n,const char*lab){for(int i=0;i<n;i++)if(!strcmp(q[i].op,"label")&&!strcmp(q[i].result,lab))return i;return -1;}
int build_cfg(const Quad*q,int n,CFG*cfg){int leader[MAX_QUADS]={0};leader[0]=1;for(int i=0;i<n;i++){if(!strcmp(q[i].op,"goto")||!strcmp(q[i].op,"if")){int t=label_index(q,n,q[i].result);if(t>=0)leader[t]=1;if(i+1<n)leader[i+1]=1;}}int starts[MAX_BLOCKS],s=0;for(int i=0;i<n;i++)if(leader[i])starts[s++]=i;cfg->count=s;for(int b=0;b<s;b++){cfg->blocks[b].start=starts[b];cfg->blocks[b].end=(b+1<s?starts[b+1]:n)-1;cfg->blocks[b].nsucc=0;}for(int b=0;b<s;b++){int i=cfg->blocks[b].end;if(i<0)continue;if(!strcmp(q[i].op,"goto")){int t=label_index(q,n,q[i].result);for(int x=0;x<s;x++)if(starts[x]==t)cfg->blocks[b].succ[cfg->blocks[b].nsucc++]=x;}else if(!strcmp(q[i].op,"if")){int t=label_index(q,n,q[i].result);for(int x=0;x<s;x++)if(starts[x]==t)cfg->blocks[b].succ[cfg->blocks[b].nsucc++]=x;if(b+1<s)cfg->blocks[b].succ[cfg->blocks[b].nsucc++]=b+1;}else if(b+1<s)cfg->blocks[b].succ[cfg->blocks[b].nsucc++]=b+1;}return s;}
void dump_cfg(const Quad*q,const CFG*cfg){printf("--- CONTROL FLOW GRAPH ---\n");for(int b=0;b<cfg->count;b++){printf("B%d: quads %d..%d ->",b,cfg->blocks[b].start,cfg->blocks[b].end);for(int j=0;j<cfg->blocks[b].nsucc;j++)printf(" B%d",cfg->blocks[b].succ[j]);printf("\n");for(int i=cfg->blocks[b].start;i<=cfg->blocks[b].end;i++)printf("    %d: %s %s %s %s\n",i,q[i].op,q[i].arg1,q[i].arg2,q[i].result);}printf("\n");}
